//! Commit ids and event counts.

use std::{fmt, num::NonZeroU16};

use time::OffsetDateTime;
use uuid::Uuid;

/// Identifies one append: the events it wrote share it.
///
/// Always a UUIDv7 generated by the client, so a retried append can be recognised and the commit's time is
/// part of its id. Within a stream, commit ids increase; the store rejects one that does not.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct CommitId(Uuid);

impl CommitId {
    /// A new id for the current time. Ids generated in one process increase.
    pub fn generate() -> Self {
        Self(Uuid::now_v7())
    }

    /// Wraps an id read from storage. Returns `None` if it is not a UUIDv7.
    pub fn from_uuid(id: Uuid) -> Option<Self> {
        (id.get_version_num() == 7).then_some(Self(id))
    }

    /// The underlying id.
    pub const fn as_uuid(&self) -> Uuid {
        self.0
    }

    /// When the commit was created, to the millisecond.
    pub fn recorded_at(&self) -> OffsetDateTime {
        let millis = self.0.get_timestamp().map(|ts| {
            let (seconds, nanos) = ts.to_unix();
            i128::from(seconds) * 1_000_000_000 + i128::from(nanos)
        });

        // A v7 id always carries a 48-bit millisecond timestamp, which is in range.
        millis
            .and_then(|nanos| OffsetDateTime::from_unix_timestamp_nanos(nanos).ok())
            .unwrap_or(OffsetDateTime::UNIX_EPOCH)
    }
}

impl fmt::Display for CommitId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

/// How many events one commit holds: 1 to [`EventCount::MAX`] (32767, because `commits.event_count` is an
/// `int2`).
///
/// ```
/// use pges_core::commit;
///
/// const THREE: commit::EventCount = match commit::EventCount::new(3) {
///     Some(count) => count,
///     None => panic!("out of range"),
/// };
///
/// assert_eq!(THREE.get(), 3);
/// assert_eq!(commit::EventCount::new(0), None);
/// assert_eq!(commit::EventCount::from_len(40_000), None);
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct EventCount(NonZeroU16);

impl EventCount {
    /// One event.
    pub const ONE: Self = Self(NonZeroU16::MIN);

    /// The most events one commit can hold: 32767.
    pub const MAX: Self = match NonZeroU16::new(i16::MAX.unsigned_abs()) {
        Some(max) => Self(max),
        None => Self::ONE,
    };

    /// `count`, or `None` if it is 0 or above [`EventCount::MAX`].
    pub const fn new(count: u16) -> Option<Self> {
        if count > Self::MAX.0.get() {
            return None;
        }

        match NonZeroU16::new(count) {
            Some(count) => Some(Self(count)),
            None => None,
        }
    }

    /// The length of a list of events, or `None` if it is empty or longer than [`EventCount::MAX`].
    pub const fn from_len(len: usize) -> Option<Self> {
        if len > Self::MAX.0.get() as usize {
            return None;
        }

        Self::new(len as u16)
    }

    /// The number.
    pub const fn get(self) -> u16 {
        self.0.get()
    }

    /// The number as an `i16`, which always holds it (the `int2` of `commits.event_count`).
    pub const fn to_i16(self) -> i16 {
        self.0.get().cast_signed()
    }
}

impl fmt::Display for EventCount {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_ids_increase_and_carry_their_time() {
        let before = OffsetDateTime::now_utc();
        let a = CommitId::generate();
        let b = CommitId::generate();
        let after = OffsetDateTime::now_utc();

        assert!(a < b);
        assert!(a.recorded_at() >= before - time::Duration::milliseconds(1));
        assert!(a.recorded_at() <= after);
    }

    #[test]
    fn accepts_only_v7() {
        assert!(CommitId::from_uuid(Uuid::now_v7()).is_some());
        assert!(CommitId::from_uuid(Uuid::nil()).is_none());
    }

    #[test]
    fn event_counts_fit_a_commit() {
        assert_eq!(EventCount::new(0), None);
        assert_eq!(EventCount::new(1), Some(EventCount::ONE));
        assert_eq!(EventCount::new(32767), Some(EventCount::MAX));
        assert_eq!(EventCount::new(32768), None);
        assert_eq!(EventCount::from_len(0), None);
        assert_eq!(EventCount::from_len(32767), Some(EventCount::MAX));
        assert_eq!(EventCount::from_len(usize::MAX), None);
        assert_eq!(usize::from(EventCount::MAX.get()), crate::frame::MAX_EVENTS);
        assert_eq!(EventCount::MAX.to_i16(), i16::MAX);
    }
}
